import React, { useState } from 'react';
import Sidebar from '../components/Sidebar';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function LmsDashboard({ handleLogout }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  const [stats] = useState({
    totalStudents: '1,250',
    totalTeachers: '45',
    activeClasses: '120',
    inactiveStudents: '25'
  });

  const [growthData] = useState({
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
    datasets: [{
      label: 'Enrollment Growth',
      data: [10, 32, 25, 48, 80],
      borderColor: '#15803d',
      backgroundColor: 'rgba(21, 128, 61, 0.1)',
      tension: 0.4,
      fill: true
    }]
  });

  return (
    <div style={{ display: 'flex', width: '100%', minHeight: '100vh', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' }}>
      
      <Sidebar
        currentSubPage={currentSubPage}
        setCurrentSubPage={setCurrentSubPage}
        onLogoutClick={handleLogout}
      />

      <div style={{ flex: 1, padding: '30px', display: 'flex', flexDirection: 'column', gap: '25px' }}>
        
        <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
          <button
            onClick={handleLogout}
            style={{
              backgroundColor: '#dc2626',
              color: '#fff',
              border: 'none',
              padding: '10px 20px',
              borderRadius: '8px',
              cursor: 'pointer',
              fontWeight: 'bold'
            }}
          >
            🚪 Logout
          </button>
        </div>

        {currentSubPage === 'Overview' && (
          <>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px' }}>
              {[
                { t: 'Total Students', v: stats.totalStudents, i: '👨‍🎓' },
                { t: 'Total Teachers', v: stats.totalTeachers, i: '👩‍🏫' },
                { t: 'Active Classes', v: stats.activeClasses, i: '🏫' },
                { t: 'Inactive Students', v: stats.inactiveStudents, i: '⚠️' }
              ].map((c, i) => (
                <div key={i} style={{ background: '#fff', padding: '20px', borderRadius: '12px', border: '1px solid #f1f5f9' }}>
                  <p style={{ margin: 0, color: '#64748b' }}>{c.t}</p>
                  <h2 style={{ margin: 0 }}>{c.v}</h2>
                </div>
              ))}
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '25px' }}>
              
              <div style={{ background: '#fff', padding: '25px', borderRadius: '12px' }}>
                <h3>Enrollment Growth</h3>
                <div style={{ height: '240px' }}>
                  <Line data={growthData} options={{ responsive: true, maintainAspectRatio: false }} />
                </div>
              </div>

              <div style={{ background: '#fff', padding: '25px', borderRadius: '12px' }}>
                <h3>Student Status</h3>
                {['Ruwan', 'John', 'Sama', 'Ramn'].map((n, i) => (
                  <div key={i} style={{ display: 'flex', justifyContent: 'space-between', padding: '8px 0' }}>
                    <span>{n}</span>
                    <span style={{ color: '#22c55e' }}>Active</span>
                  </div>
                ))}
              </div>
            </div>

            <div style={{ background: '#fff', padding: '25px', borderRadius: '12px' }}>
              <h3>Upcoming Schedule</h3>
              <p>Table content here...</p>
            </div>

            <div style={{ display: 'flex', gap: '15px', marginTop: '20px', marginBottom: '40px' }}>
              <button style={{ flex: 1, height: '55px', borderRadius: '10px', background: '#2563eb', color: '#fff', border: 'none' }}>
                Manage Students
              </button>
              <button style={{ flex: 1, height: '55px', borderRadius: '10px', border: '1px solid #ddd' }}>
                Manage Teachers
              </button>
              <button style={{ flex: 1, height: '55px', borderRadius: '10px', border: '1px solid #ddd' }}>
                Create Course
              </button>
            </div>
          </>
        )}

        {currentSubPage === 'Students' && <div>Student Management</div>}
        {currentSubPage === 'Teachers & Classes' && <div>Teachers & Classes</div>}
        {currentSubPage === 'Reports' && <div>Reports</div>}
        {currentSubPage === 'Settings' && <div>Settings</div>}

      </div>
    </div>
  );
}
